var locationInfo = {
  geo: null,
  country: null,
  state: null,
  city: null,
  postalCode: null,
  street: null,
  streetNumber: null,
  reset: function() {
    this.geo = null;
    this.country = null;
    this.state = null;
    this.city = null;
    this.postalCode = null;
    this.street = null;
    this.streetNumber = null;
  }
};

$(".fake-autofill-fields").show();
window.setTimeout(function() {
  $(".fake-autofill-fields").hide();
}, 1);

googleAutocomplete = {
  autocompleteField: function(e) {
    autocomplete = new google.maps.places.Autocomplete(document.getElementById(e));
    google.maps.event.addListener(autocomplete, "place_changed", function() {
      var e = autocomplete.getPlace(),
          o = e.address_components,
          t = e.geometry.location.lat(),
          a = e.geometry.location.lng();
      locationInfo.reset();
      locationInfo.geo = [t, a];
      for (var n = 0; n < o.length; n++) {
        var i = o[n].types[0];
        switch (i) {
          case "country":
            locationInfo.country = o[n].long_name;
            break;
          case "administrative_area_level_1":
            locationInfo.state = o[n].long_name;
            break;
          case "locality":
            locationInfo.city = o[n].long_name;
            break;
          case "postal_code":
            locationInfo.postalCode = o[n].long_name;
            break;
          case "route":
            locationInfo.street = o[n].long_name;
            break;
          case "street_number":
            locationInfo.streetNumber = o[n].long_name;
            break;
        }
      }
    });
  }
};

